1	const PROCESSING_FEE = 5;
2	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
3	const COMPONENT_BASE_PREMIUM_BY_TYPE: Record<string, number> = {
4	  rune: 25,
5	  moonstone: 25,
6	};
7	const MAIN_ITEM_BASE_PREMIUM_BY_TYPE: Record<string, number> = {
8	  sword: 100,
9	  amulet: 60,
10	  staff: 80,
11	  potion: 40,
12	};
13	const BASE_PREMIUM_BY_ITEM_TYPE: Record<string, number> = {
14	  ...MAIN_ITEM_BASE_PREMIUM_BY_TYPE,
15	  ...COMPONENT_BASE_PREMIUM_BY_TYPE,
16	};
17	const COMPONENT_BLOCK_SIZE = 3;
18	const COMPONENT_BLOCK_BASE_PREMIUM = 60;
19	const CURSED_SURCHARGE_RATE = 0.5;
20	const HIGH_ENCHANTMENT_THRESHOLD = 5;
21	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
22	const LOYALTY_MINIMUM_YEARS = 2;
23	const LOYALTY_DISCOUNT_RATE = 0.2;
24	const FOLLOW_UP_DISCOUNT_RATE = 0.15;
25	const DEDUCTIBLE = 100;
26	const CAP_MULTIPLIER = 2;
27	const HALF_REIMBURSEMENT_ENCHANTMENT_THRESHOLD = 8;
28	const HALF_REIMBURSEMENT_RATE = 0.5;
29	const FULL_REIMBURSEMENT_RATE = 1;
30	const INSURANCE_VALUE_BY_ITEM_TYPE: Record<string, number> = {
31	  sword: 1000,
32	  amulet: 600,
33	  rune: 250,
34	};
35	
36	type Item = {
37	  type: string;
38	  material?: string;
39	  enchantment?: number;
40	  cursed?: boolean;
41	};
42	
43	type Damage = {
44	  itemType: string;
45	  amount: number;
46	};
47	
48	type Incident = {
49	  cause: string;
50	  damages: Damage[];
51	};
52	
53	type Step = {
54	  op: string;
55	  items?: Item[];
56	  policy?: number;
57	  incident?: Incident;
58	};
59	
60	type Scenario = {
61	  customer: { yearsWithMHPCO: number };
62	  steps: Step[];
63	};
64	
65	type QuoteResult = {
66	  premium: number;
67	};
68	
69	type ClaimResult = {
70	  payout: number;
71	  remainingCap: number;
72	};
73	
74	type StepResult = QuoteResult | ClaimResult;
75	
76	type ScenarioOutput = {
77	  results: StepResult[];
78	};
79	
80	const isComponent = (item: Item): boolean =>
81	  item.type in COMPONENT_BASE_PREMIUM_BY_TYPE;
82	
83	const isComponentBlock = (sameTypeItems: Item[]): boolean =>
84	  sameTypeItems.length === COMPONENT_BLOCK_SIZE &&
85	  sameTypeItems.every(isComponent);
86	
87	const groupByType = (items: Item[]): Item[][] => {
88	  const distinctTypes = [...new Set(items.map((item) => item.type))];
89	  return distinctTypes.map((type) =>
90	    items.filter((item) => item.type === type),
91	  );
92	};
93	
94	const basePremiumForItem = (item: Item): number => {
95	  const basePremium = BASE_PREMIUM_BY_ITEM_TYPE[item.type];
96	  if (basePremium === undefined)
97	    throw new Error(`Unknown item type: ${item.type}`);
98	  return basePremium;
99	};
100	
101	const basePremiumForGroup = (sameTypeItems: Item[]): number => {
102	  if (isComponentBlock(sameTypeItems)) return COMPONENT_BLOCK_BASE_PREMIUM;
103	  return sameTypeItems.reduce(
104	    (total, item) => total + basePremiumForItem(item),
105	    0,
106	  );
107	};
108	
109	const basePremiumForItems = (items: Item[]): number =>
110	  groupByType(items).reduce(
111	    (total, group) => total + basePremiumForGroup(group),
112	    0,
113	  );
114	
115	const amountAtRate = (
116	  basePremium: number,
117	  rate: number,
118	  applies?: boolean,
119	): number => (applies ? basePremium * rate : 0);
120	
121	const cursedSurcharge = (item: Item): number =>
122	  amountAtRate(basePremiumForItem(item), CURSED_SURCHARGE_RATE, item.cursed);
123	
124	const enchantmentLevelOf = (item: Item): number => item.enchantment ?? 0;
125	
126	const hasHighEnchantment = (item: Item): boolean =>
127	  enchantmentLevelOf(item) >= HIGH_ENCHANTMENT_THRESHOLD;
128	
129	const highEnchantmentSurcharge = (item: Item): number =>
130	  amountAtRate(
131	    basePremiumForItem(item),
132	    HIGH_ENCHANTMENT_SURCHARGE_RATE,
133	    hasHighEnchantment(item),
134	  );
135	
136	const totalItemSurcharges = (items: Item[]): number =>
137	  items.reduce(
138	    (total, item) =>
139	      total + cursedSurcharge(item) + highEnchantmentSurcharge(item),
140	    0,
141	  );
142	
143	const firstInsuranceSurcharge = (basePremium: number): number =>
144	  basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
145	
146	const isLoyalCustomer = (yearsWithMHPCO: number): boolean =>
147	  yearsWithMHPCO >= LOYALTY_MINIMUM_YEARS;
148	
149	const loyaltyDiscount = (basePremium: number, yearsWithMHPCO: number): number =>
150	  amountAtRate(
151	    basePremium,
152	    LOYALTY_DISCOUNT_RATE,
153	    isLoyalCustomer(yearsWithMHPCO),
154	  );
155	
156	const followUpDiscount = (basePremium: number, isFollowUp: boolean): number =>
157	  amountAtRate(basePremium, FOLLOW_UP_DISCOUNT_RATE, isFollowUp);
158	
159	const premiumBeforeProcessingFee = (
160	  items: Item[],
161	  yearsWithMHPCO: number,
162	  isFollowUp: boolean,
163	): number => {
164	  const basePremium = basePremiumForItems(items);
165	  return (
166	    basePremium +
167	    totalItemSurcharges(items) +
168	    firstInsuranceSurcharge(basePremium) -
169	    loyaltyDiscount(basePremium, yearsWithMHPCO) -
170	    followUpDiscount(basePremium, isFollowUp)
171	  );
172	};
173	
174	const isFollowUpQuote = (stepIndex: number): boolean => stepIndex > 0;
175	
176	const isClaimStep = (step: Step): boolean => step.op === "claim";
177	
178	const insuranceSumForItems = (items: Item[]): number =>
179	  items.reduce(
180	    (total, item) => total + INSURANCE_VALUE_BY_ITEM_TYPE[item.type],
181	    0,
182	  );
183	
184	const capForItems = (items: Item[]): number =>
185	  insuranceSumForItems(items) * CAP_MULTIPLIER;
186	
187	const damagedItemFor = (damage: Damage, policyItems: Item[]): Item => {
188	  const damagedItem = policyItems.find(
189	    (item) => item.type === damage.itemType,
190	  );
191	  if (damagedItem === undefined)
192	    throw new Error(`Item type not covered by the policy: ${damage.itemType}`);
193	  return damagedItem;
194	};
195	
196	const reimbursementRateFor = (item: Item): number =>
197	  enchantmentLevelOf(item) >= HALF_REIMBURSEMENT_ENCHANTMENT_THRESHOLD
198	    ? HALF_REIMBURSEMENT_RATE
199	    : FULL_REIMBURSEMENT_RATE;
200	
201	const payoutForDamage = (damage: Damage, policyItems: Item[]): number =>
202	  damage.amount * reimbursementRateFor(damagedItemFor(damage, policyItems)) -
203	  DEDUCTIBLE;
204	
205	const countWhere = <T>(values: T[], matches: (value: T) => boolean): number =>
206	  values.filter(matches).length;
207	
208	const assertDamageCountsWithinPolicy = (
209	  damages: Damage[],
210	  policyItems: Item[],
211	): void => {
212	  for (const damage of damages) {
213	    const damagedCount = countWhere(
214	      damages,
215	      (entry) => entry.itemType === damage.itemType,
216	    );
217	    const insuredCount = countWhere(
218	      policyItems,
219	      (item) => item.type === damage.itemType,
220	    );
221	    if (damagedCount > insuredCount)
222	      throw new Error(
223	        `More damage entries than insured items of type: ${damage.itemType}`,
224	      );
225	  }
226	};
227	
228	const totalPayoutForDamages = (damages: Damage[], policyItems: Item[]): number =>
229	  damages.reduce(
230	    (total, damage) => total + payoutForDamage(damage, policyItems),
231	    0,
232	  );
233	
234	const policyIndexOf = (step: Step): number => step.policy ?? 0;
235	
236	const policyItemsAt = (policyIndex: number, steps: Step[]): Item[] =>
237	  steps[policyIndex].items ?? [];
238	
239	const damagesFor = (step: Step): Damage[] => step.incident?.damages ?? [];
240	
241	const claimResultFor = (
242	  step: Step,
243	  steps: Step[],
244	  remainingCapByPolicy: Map<number, number>,
245	): ClaimResult => {
246	  const policyIndex = policyIndexOf(step);
247	  const policyItems = policyItemsAt(policyIndex, steps);
248	  const damages = damagesFor(step);
249	  const availableCap =
250	    remainingCapByPolicy.get(policyIndex) ?? capForItems(policyItems);
251	  assertDamageCountsWithinPolicy(damages, policyItems);
252	  const payoutBeforeCap = Math.floor(
253	    totalPayoutForDamages(damages, policyItems),
254	  );
255	  const payout = Math.min(payoutBeforeCap, availableCap);
256	  const remainingCap = availableCap - payout;
257	  remainingCapByPolicy.set(policyIndex, remainingCap);
258	  return { payout, remainingCap };
259	};
260	
261	const quoteResultFor = (
262	  step: Step,
263	  yearsWithMHPCO: number,
264	  stepIndex: number,
265	): QuoteResult => ({
266	  premium: Math.ceil(
267	    premiumBeforeProcessingFee(
268	      step.items ?? [],
269	      yearsWithMHPCO,
270	      isFollowUpQuote(stepIndex),
271	    ) + PROCESSING_FEE,
272	  ),
273	});
274	
275	export const runScenario = (scenario: Scenario): ScenarioOutput => {
276	  const remainingCapByPolicy = new Map<number, number>();
277	  return {
278	    results: scenario.steps.map((step, stepIndex) =>
279	      isClaimStep(step)
280	        ? claimResultFor(step, scenario.steps, remainingCapByPolicy)
281	        : quoteResultFor(step, scenario.customer.yearsWithMHPCO, stepIndex),
282	    ),
283	  };
284	};
